import{_ as e,o as r,c as a,a7 as o}from"./chunks/framework.C4ZIv4ii.js";const d="/falconcms/screenshots/promotion-editor.webp",u=JSON.parse('{"title":"Promotions","description":"","frontmatter":{},"headers":[],"relativePath":"ecommerce/promotions.md","filePath":"ecommerce/promotions.md","lastUpdated":1788112837000}'),i={name:"ecommerce/promotions.md"};function n(s,t,h,c,l,m){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="promotions" tabindex="-1">Promotions <a class="header-anchor" href="#promotions" aria-label="Permalink to &quot;Promotions&quot;">​</a></h1><p>Promotions are automatic offers — buy two get one free, 20% off a category, a discount once the cart passes an amount. Unlike <a href="/falconcms/ecommerce/coupons.html">coupons</a>, the customer types nothing: the rules are evaluated on every cart read and applied on their own.</p><p>Manage them under <strong>Admin → Shop → Promotions</strong>.</p><p><img src="'+d+'" alt="The promotion editor"></p><p><em>A promotion is written as three blocks — Basics, the Condition the cart must meet, and the Reward it earns.</em></p><h2 id="creating-a-promotion" tabindex="-1">Creating a promotion <a class="header-anchor" href="#creating-a-promotion" aria-label="Permalink to &quot;Creating a promotion&quot;">​</a></h2><p>A promotion is a <strong>trigger</strong> (what has to be in the cart) and a <strong>reward</strong> (what the customer gets for it).</p><h3 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>product</code></td><td>Specific products must be in the cart</td></tr><tr><td><code>category</code></td><td>Anything from the chosen categories counts</td></tr><tr><td><code>cart_total</code></td><td>The cart subtotal must reach an amount</td></tr></tbody></table><p><strong>Trigger quantity</strong> is how many units are needed. For <code>cart_total</code> it is the amount.</p><h3 id="reward" tabindex="-1">Reward <a class="header-anchor" href="#reward" aria-label="Permalink to &quot;Reward&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>free_item</code></td><td>The reward units cost nothing</td></tr><tr><td><code>percent_off</code></td><td>A percentage off the reward units</td></tr><tr><td><code>fixed_off</code></td><td>A fixed amount off the reward units</td></tr></tbody></table><p><strong>Reward scope</strong> decides what the reward lands on:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Meaning</th></tr></thead><tbody><tr><td><code>same</code></td><td>The same items that triggered the offer</td></tr><tr><td><code>specific</code></td><td>Particular products you choose</td></tr><tr><td><code>category</code></td><td>Anything from the chosen categories</td></tr></tbody></table><p><strong>Reward quantity</strong> is how many units are rewarded per application.</p><h2 id="worked-example-—-buy-2-get-1-free" tabindex="-1">Worked example — buy 2, get 1 free <a class="header-anchor" href="#worked-example-—-buy-2-get-1-free" aria-label="Permalink to &quot;Worked example — buy 2, get 1 free&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Trigger type</td><td><code>product</code></td></tr><tr><td>Trigger products</td><td>T-Shirt</td></tr><tr><td>Trigger quantity</td><td>2</td></tr><tr><td>Reward type</td><td><code>free_item</code></td></tr><tr><td>Reward scope</td><td><code>same</code></td></tr><tr><td>Reward quantity</td><td>1</td></tr></tbody></table><p>Add two T-shirts and the cart offers a third free. Add four and the offer applies twice — unless <strong>Max applications</strong> caps it.</p><h2 id="limits-and-scheduling" tabindex="-1">Limits and scheduling <a class="header-anchor" href="#limits-and-scheduling" aria-label="Permalink to &quot;Limits and scheduling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Priority</strong></td><td>Lower numbers are evaluated first when several promotions could apply</td></tr><tr><td><strong>Max applications</strong></td><td>How many times one cart may claim the offer</td></tr><tr><td><strong>Usage limit</strong></td><td>How many times the promotion may be claimed across all orders</td></tr><tr><td><strong>Starts / Ends</strong></td><td>The window in which it is live</td></tr><tr><td><strong>Active</strong></td><td>Switch it off without deleting it</td></tr></tbody></table><p>The usage limit is claimed with a conditional update at checkout, so two orders completing at the same instant cannot both take the last one.</p><h2 id="what-the-customer-sees" tabindex="-1">What the customer sees <a class="header-anchor" href="#what-the-customer-sees" aria-label="Permalink to &quot;What the customer sees&quot;">​</a></h2><ul><li>On the <strong>cart</strong>, an offer they nearly qualify for is shown as a prompt — <em>Add one more and get a T-Shirt free</em> — and it updates as the cart changes, without a reload.</li><li>A claimed reward appears as its own discount line, named after the promotion.</li><li><strong>Order details</strong> list the promotion alongside the items it applied to, so neither the customer nor your staff has to work out why the total is lower.</li></ul><h2 id="custom-message" tabindex="-1">Custom message <a class="header-anchor" href="#custom-message" aria-label="Permalink to &quot;Custom message&quot;">​</a></h2><p><strong>Cart message</strong> replaces the default prompt with your own wording. Leave it empty and the generated text is used.</p><h2 id="nothing-is-stored-in-the-cart" tabindex="-1">Nothing is stored in the cart <a class="header-anchor" href="#nothing-is-stored-in-the-cart" aria-label="Permalink to &quot;Nothing is stored in the cart&quot;">​</a></h2><p>Rewards are recalculated from the rules on every cart read. Change a promotion and every live basket reflects it immediately; there is no stale discount to clean up.</p>',27)])])}const g=e(i,[["render",n]]);export{u as __pageData,g as default};
